<?php if(in_array($kind,['claims','invoices'],true)&&module_enabled('Salary')):$links=EmployeeMoney::links($record['id']); ?>
<details><summary><?= e(t('Money ledger links')) ?></summary><p><?= e(t('Post only if this payment is not already recorded in Money. Receipts follow your current income allocation rules. Reverse a linked entry from Money before correcting it.')) ?></p>
<?php if($links['expense_id']): ?><p><?= e(t('Expense #')) ?><?= e($links['expense_id']) ?></p><?php elseif($kind==='claims'): ?><form class="inline" method="post" action="/employee/claims/<?= e($record['id']) ?>/expense" data-confirm="Record this claim as an actual expense and debit the selected account?"><?= csrf_field() ?><label><?= e(t('Account')) ?><select name="account_id" required><?php foreach(Db::all('SELECT id,name FROM accounts')as $a): ?><option value="<?= e($a['id']) ?>"><?= e($a['name']) ?></option><?php endforeach; ?></select></label><label><?= e(t('Category')) ?><select name="category_id" required><?php foreach(Db::all('SELECT id,name FROM expense_categories')as $a): ?><option value="<?= e($a['id']) ?>"><?= e($a['name']) ?></option><?php endforeach; ?></select></label><button class="secondary"><?= e(t('Record actual claim expense')) ?></button></form><?php endif; ?>
<?php if($links['income_id']): ?><p><?= e(t('Income #')) ?><?= e($links['income_id']) ?></p><?php elseif($d['state']==='paid'&&($kind==='claims'||$d['currency']==='LKR')): ?><form class="inline" method="post" action="/employee/<?= e($kind) ?>/<?= e($record['id']) ?>/receipt" data-confirm="Record this receipt as income using current allocation rules?"><?= csrf_field() ?><label><?= e(t('Received on')) ?><input type="date" name="date" required value="<?= e(ui_date('Y-m-d')) ?>"></label><button class="secondary"><?= e(t('Record received money')) ?></button></form><?php endif; ?></details>
<?php endif; ?>
